comment on table public.system_state is 'Persistent monitor state such as bootstrap status and last successful FIRMS poll.';
comment on table public.oblasts is 'Administrative regions used for assigning NASA FIRMS detections to a region.';
comment on table public.fire_events is 'Deduplicated thermal-anomaly events built from one or more FIRMS detections.';
comment on table public.detections is 'Raw normalized NASA FIRMS observations. detection_hash prevents duplicate ingestion.';
comment on table public.osint_evidence is 'Public-source OSINT evidence correlated to thermal events by time and distance. Correlation does not establish causation.';
comment on table public.ground_sensor_latest is 'Latest public ground environmental measurements used as OSINT context. Values are source observations, not causal attribution to a fire_event.';
comment on table public.environment_source_registry is 'Explicit allow-list for low-volume environmental JSON sources. Do not use this table for mass scraping.';
comment on table public.geo_osint_event_cache is 'Compact event-centric OpenStreetMap Geo OSINT cache populated by Geofabrik Postpass. No GitHub Actions or live Overpass dependency.';
comment on table public.event_evidence_reports is 'Stage 30 evidence report cache. Coverage is availability of evidence classes, not a confidence, risk or causal score.';
comment on table public.event_osint_dossiers is 'Cached multi-source OSINT dossier. Flags are descriptive context predicates and do not establish causation.';
comment on table public.satellite_surface_evidence is 'Sentinel-2 L2A before/after surface spectral evidence. dNBR/NDVI are environmental change metrics and are not causal attribution.';
comment on column public.fire_events.lifecycle_status is 'User-facing lifecycle state for the single Telegram card of this event.';
comment on column public.fire_events.telegram_last_observation_count is 'Observation count represented by the last Telegram send/edit.';
comment on column public.fire_events.telegram_last_seen_snapshot is 'Event last_seen represented by the last Telegram send/edit.';
comment on column public.fire_events.telegram_last_frp is 'Latest detection FRP represented by the last Telegram send/edit.';
comment on column public.fire_events.telegram_last_status is 'Lifecycle status represented by the last Telegram send/edit.';
comment on column public.fire_events.telegram_last_update_at is 'Timestamp of the last successful Telegram send/edit for this event.';
comment on column public.fire_events.telegram_message_kind is 'Telegram message representation used for later in-place edits: photo or text.';
comment on column public.fire_events.osm_context_type is 'Derived OSM land-use/context class for the event';
comment on column public.fire_events.osm_context_score is '0-100 confidence/coverage score for derived OSM context';
comment on column public.fire_events.osm_features is 'Top nearby OSM features used to derive event context';
comment on column public.oblasts.geom is 'Administrative boundary in EPSG:4326.';
comment on column public.event_evidence_reports.viewer_token_hash is 'SHA-256 hash of the temporary report viewer token. Raw token is never persisted.';
comment on column public.event_evidence_reports.viewer_expires_at is 'Expiry of the temporary report viewer token.';
comment on column public.satellite_surface_evidence.algorithm_version is 'Spectral calculation version. v2 uses Earth Search boa_offset_applied to avoid double-applying the Sentinel-2 BOA offset.';
comment on column public.satellite_surface_evidence.visual_storage_path is 'Private Supabase Storage object path for the Stage 29.1 before/after evidence montage.';
comment on column public.geo_osint_event_cache.infra_profile_version is 'Version of the OpenInfraMap-compatible OSM infrastructure taxonomy used by GeoWatch.';
comment on column public.geo_osint_event_cache.infrastructure_counts is 'Counts by detailed infrastructure type within the event query radius.';
comment on column public.geo_osint_event_cache.infrastructure_features is 'Compact nearest infrastructure features with selected public OSM tags.';
comment on column public.geo_osint_event_cache.nearest_infrastructure is 'Nearest retained infrastructure feature, if any.';
comment on column public.geo_osint_event_cache.openinframap_url is 'Human-review deep link centered on the event in OpenInfraMap.';
